function Breakdown({
  rows,
  groupBy,
  empty,
}: {
  rows: CrmRow[];
  groupBy: "stage_id" | "representative_id";
  empty: string;
}) {
  const totals = new Map<string, { count: number; value: number }>();
  rows.forEach((row) => {
    const id = String(row[groupBy] ?? "—");
    const current = totals.get(id) ?? { count: 0, value: 0 };
    current.count += 1;
    current.value += Number(row.estimated_value ?? 0);
